var WIDTH, HEIGHT;
let grid;
let img, curImg, imgs;
let canvas, bg, tex;
let font, shaded, shading;
let text;
let waveShader;

function preload() {	
	grid = loadImage("https://openprocessing.org/sketch/1622712/files/griduv.jpg");

	font = loadFont("https://openprocessing.org/sketch/1622712/files/HelveticaNeue-Bold.otf");
}

function setup() {
	canvas = createCanvas(windowWidth, windowHeight, WEBGL);
	noStroke();

	WIDTH = HEIGHT = max(windowWidth, windowHeight) - 50;

	shaded = createGraphics(WIDTH, HEIGHT, WEBGL);
	tex = createGraphics(WIDTH, HEIGHT);
	shading = new p5.Shader(canvas._renderer, vert, frag);
	waveShader = createShader(waveVert, waveFrag);

	imgs = [drawFlag(WIDTH, HEIGHT)];

	text = "Слава Україні\n\nStop\nThe\nWar";

	setImg(0);

	initMapping();
}

function setImg(index){
	curImg = index;
	if(curImg >= imgs.length) curImg = 0;
	if(curImg < 0) curImg = imgs.length-1;

	img = imgs[curImg];
	bg = createGraphics(img.width, img.height);
	bg.image(img, 0, 0, img.width, img.height);

	generateText();
}

function generateText(){
	tex.clear();
	tex.fill(0);
	tex.textFont(font);
	tex.textSize(120);
	tex.textLeading(100);
	tex.textAlign(CENTER, CENTER);
	tex.text(text, WIDTH/2, HEIGHT/2-30);
}

function draw() {
	background(0);
	scale(1.6, 1);
	let mapping = isCloseToPoints();

	shaded.shader(shading);
	shading.setUniform('iTime', millis()/3000);
	shading.setUniform('bg', mapping ? grid : bg);
	shading.setUniform('tex', tex);
	shading.setUniform('canvasSize', [WIDTH, HEIGHT]);
	shading.setUniform('realSize', [img.width, img.height]);
	shaded.rect(0, 0, WIDTH, HEIGHT);

	const detail = 64;

	shader(waveShader)
	waveShader.setUniform('resolution', [width, height])
	waveShader.setUniform('time', millis()/1000)
	waveShader.setUniform('mouse', [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))])
	waveShader.setUniform('tex', shaded)
	smoothQuad(vecTL.x, vecTL.y, vecTR.x, vecTR.y, vecBR.x, vecBR.y, vecBL.x, vecBL.y, detail, detail)

	if(mapping){
		resetShader();
		drawDrag();
	}
}

function keyPressed(){
	//LEFT and RIGHT
	if(keyCode == 37 || keyCode == 39){
		if(keyCode == 37) setImg(curImg-1);
		else setImg(curImg+1);
		return;
	}

	//TOP
	if(keyCode == 38) {
		//reset text
		text = "";
		generateText();
		return;
	}

	//DOWN
	if(keyCode == 40){
		let fs = fullscreen();
    fullscreen(!fs);
		return;
	}

	const ignoredChars = [
		9,//TAB
		16,//SHIFT
		17,//CTRL
		18,//ALT
		20,//CAPSLOCK
		37,//LEFT
		38,//TOP
		39,//RIGHT
		40,//DOWN
		54,//^
		91,//Windows key
		222,//'
		192,//~
	];
	if(ignoredChars.includes(keyCode)) return;

	if(keyCode==8){//backspace
		text = text.substring(0, text.length - 1);
	}else if(keyCode==13){//break line
		text += "\n";
	}else{
		text += key;
	}
	generateText();
}

/**
Mapping
**/
let vecTL, vecTR, vecBL, vecBR;

function initMapping(){
	vecTL = createPoint(-WIDTH/2, -HEIGHT/2);//TOP LEFT
	vecTR = createPoint(WIDTH/2, -HEIGHT/2);//TOP RIGHT
	vecBR = createPoint(WIDTH/2, HEIGHT/2);//BOTTOM LEFT
	vecBL = createPoint(-WIDTH/2, HEIGHT/2);//BOTTOM RIGHT
}

function createPoint(x, y){
	let vec = createVector(x, y);
	addDrag(vec);
	return vec;
}

function mousePressed() {
  dragMousePressed();
}

function mouseReleased() {
  dragMouseReleased();
}

function mouseDragged() {
  dragMouseDragged();
}

function drawFlag(w, h) {
	var colors = ["#fdfefe", "#fcdd0c", "#eb7712", "#da161a", "#732b65", "#1646ad", "#078930"];
	var size = min(w, h);
	var g = createGraphics(size, size);
	g.noStroke();
	g.fill("#0057b7");
	g.rect(0, 0, size, size/2);
	g.fill("#ffd700");
	g.rect(0, size/2, size, size/2);
	return g;
}

function mod(n, m) {
    return ((n%m)+m)%m;
}

// === Tab: shader ===
const vert = `
attribute vec3 aPosition;
attribute vec2 aTexCoord;
varying vec2 vTexCoord;

void main() {
  vTexCoord = aTexCoord;
	vec4 positionVec4 = vec4(aPosition, 1.0);
  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;
	gl_Position = positionVec4;
}`;

const frag=`
precision mediump float;

// texcoords from the vertex shader
varying vec2 vTexCoord;
uniform float iTime;
uniform vec2 canvasSize;
uniform vec2 realSize;
uniform sampler2D tex;
uniform sampler2D bg;

void main()
{
	vec2 uv = vTexCoord;
	//invert texture	
	uv.y = 1. - uv.y;

	uv -= 0.5;
	uv *= canvasSize/realSize;//correct ratio
	uv *= min(realSize.x/canvasSize.x, realSize.y/canvasSize.y);//correct fit
	uv += 0.5;

	vec4 bgColor = texture2D(bg, uv);

	//wave
	vec2 wave = vec2(0.,0.);
	wave.x += sin(uv.y*5.+iTime*4.)*cos(uv.x*12.+iTime*2.)*sin(uv.y*32.+iTime)*0.01;
	wave.y += cos(uv.y*5.+iTime*2.)*sin(uv.y*12.+iTime*3.)*sin(uv.x*12.+iTime)*0.01;
	//uv += wave;

	vec4 text = texture2D(tex, uv);
	gl_FragColor = mix(text, bgColor, 1.-text.a);
	//gl_FragColor = bgColor + text;
}`

// === Tab: smoothQuad ===
p5.prototype.smoothQuad = function(x1, y1, x2, y2, x3, y3, x4, y4, detailX, detailY) {
	if (typeof detailX === 'undefined') {
    detailX = 8;
  }
  if (typeof detailY === 'undefined') {
    detailY = 8;
  }

  const gId = `smoothQuad|${x1}|${y1}|${x2}|${y2}|${x3}|${y3}|${x4}|${y4}|${detailX}|${detailY}`;

	if (!this._renderer.geometryInHash(gId)) {
		const smoothQuadGeom = new p5.Geometry(detailX, detailY, function() {
			//algorithm adapted from c++ to js
			//https://stackoverflow.com/questions/16989181/whats-the-correct-way-to-draw-a-distorted-plane-in-opengl/16993202#16993202
			let xRes = 1.0 / (this.detailX - 1);
			let yRes = 1.0 / (this.detailY - 1);
			for(let y = 0; y < this.detailY; y++){
				for(let x = 0; x < this.detailX; x++){
					let pctx  = x * xRes;
					let pcty  = y * yRes;

					let linePt0x  = (1 - pcty) * x1 + pcty * x4;
					let linePt0y  = (1 - pcty) * y1 + pcty * y4;
					let linePt1x  = (1 - pcty) * x2 + pcty * x3;
					let linePt1y  = (1 - pcty) * y2 + pcty * y3;

					let ptx       = (1-pctx) * linePt0x + pctx * linePt1x;
					let pty       = (1-pctx) * linePt0y + pctx * linePt1y;

					this.vertices.push(new p5.Vector(ptx, pty));
      		this.uvs.push([pctx, pcty]);
				}
			}
		});

		//compute faces and uvs
		smoothQuadGeom.faces = [];

		for(let y = 0; y < detailY-1; y++){
			for(let x = 0; x < detailX-1; x++){
				let pt0 = x + y * detailX;
				let pt1 = (x + 1) + y * detailX;
				let pt2 = (x + 1) + (y + 1) * detailX;
				let pt3 = x + (y + 1) * detailX;
				smoothQuadGeom.faces.push([pt0, pt1, pt2]);
				smoothQuadGeom.faces.push([pt0, pt2, pt3]);
			}
		}
		smoothQuadGeom
			.computeNormals()
      ._makeTriangleEdges()
      ._edgesToVertices();
		this._renderer.createBuffers(gId, smoothQuadGeom);
  }
  this._renderer.drawBuffersScaled(gId, 1, 1, 1);

	return this;
}

// === Tab: dragPoints ===
let dragging = false;
let selectedIndex = -1;
let dragabble = [];
let startDragPos;
const DRAG_SIZE = 30;

function addDrag(vec) 
{
  dragabble.push(vec);
}

function drawDrag() 
{
	for (let i=0; i < dragabble.length; i++) {
    fill(selectedIndex==i ? 100 : 255);
    circle( dragabble[i].x, dragabble[i].y, DRAG_SIZE) ;
  }
}

function dragMousePressed() {
  findSelected();
}

function dragMouseReleased() {
  selectedIndex = -1;
}

//bugfix, this function is called more than once
let lastFrameCount;
function dragMouseDragged() {
  if (selectedIndex == -1 || lastFrameCount == frameCount) return;
	lastFrameCount = frameCount;
  dragabble[selectedIndex].add((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - startDragPos.x, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - startDragPos.y, 0);
	startDragPos.x = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
	startDragPos.y = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));
}

function findSelected() {
	selectedIndex = -1;
	const MIN_DIST = pow(DRAG_SIZE, 3);
	let mX = getMouseX();
	let mY = getMouseY();
	let closest = 999999;
  for (let i=0; i < dragabble.length; i++) {
 		let distX = dragabble[i].x - mX;
		let distY = dragabble[i].y - mY;
		let distance = distX * distX + distY * distY;
		if(distance < MIN_DIST && distance < closest){
			closest = distance;
			selectedIndex = i;
			startDragPos = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
		}
  }
}

function isCloseToPoints(){
	var MIN_DIST = pow(DRAG_SIZE, 3);
	var mX = getMouseX();
	var mY = getMouseY();
  for (let i=0; i < dragabble.length; i++) {
 		var distX = dragabble[i].x - mX;
		var distY = dragabble[i].y - mY;
		var distance = distX * distX + distY * distY;
		if(distance < MIN_DIST){
			return true;
		}
  }
	return false;
}

function getMouseX(){
	return (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width/2;//WEBGL
	//return (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));//P2D
}

function getMouseY(){
	return (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height/2;//WEBGL
	//return (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));//P2D
}

function getPmouseX(){
	return (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width/2;//WEBGL
	//return (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));//P2D
}

function getPmouseY(){
	return (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height/2;//WEBGL
	//return (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));//P2D
}

// === Tab: waveShader ===
const waveVert = `
	precision highp float;

    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;
		varying vec4 var_centerGlPosition;//origin

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;
		uniform float time;


    void main() {
      vec3 pos = aPosition;

			//wave
			vec2 wave = vec2(0.,0.);
			wave.x += cos(pos.y*0.012+time*2.)*sin(pos.x*0.032+time*0.05)*10.05;
			wave.y += sin(pos.x*0.032+-time*2.)*cos(pos.x*0.012+-time*1.33)*50.05;
			pos.x += wave.x;
			pos.z += wave.y;

			vec4 posOut = uProjectionMatrix * uModelViewMatrix * vec4(pos, 1.0);

      gl_Position = posOut;

      // set out value
      var_vertPos      = pos;
      var_vertNormal   = aNormal;
      var_vertTexCoord = aTexCoord;
			var_centerGlPosition = uProjectionMatrix * uModelViewMatrix * vec4(0., 0., 0., 1.);
    }
`;

const waveFrag = `
	precision highp float;

	// Processing specific input
	uniform float time;
	uniform vec2 resolution;
	uniform vec2 mouse;
	uniform sampler2D tex;

	// Layer between Processing and Shadertoy uniforms
	vec3 iResolution = vec3(resolution,0.0);
	vec2 iMouse = vec2(mouse.xy);

	#define PI 3.1415926535
	#define iTime time
	//#define fragCoord gl_FragCoord.xy
	#define fragCoord var_vertTexCoord.xy * iResolution.xy
	#define fragColor gl_FragColor

	//attributes, in
    varying vec3 var_vertPos;
	varying vec4 var_centerGlPosition;
	varying vec3 var_vertNormal;
	varying vec2 var_vertTexCoord;

	void main(){
		vec2 uv = fragCoord / iResolution.xy;
		vec4 colTex = texture2D(tex, uv);
		fragColor = colTex * (var_vertPos.z/80.+1.3);
	}
`;

